# iNaturalist amphibians near EBTL
curl -sL 'https://api.inaturalist.org/v1/observations?taxon_id=20978&lat=12.733937&lng=78.183437&radius=10&per_page=200&order=desc&order_by=observed_on' | /tmp/venv/bin/python -c '
import sys,json,math
d=json.load(sys.stdin)
print("total:", d.get("total_results"))
lat,lon=12.733937,78.183437
def dist(a,b):
    return math.hypot((a-lat)*111,(b-lon)*111*math.cos(math.radians(lat)))
obs=d.get("results",[])
spp={}
rows=[]
for o in obs:
    t=o.get("taxon") or {}
    name=t.get("name") or "?"
    spp[name]=spp.get(name,0)+1
    la=o.get("geojson",{}).get("coordinates",[None,None])
    # geojson is lon,lat
    if la and la[0] is not None:
        rows.append((dist(la[1],la[0]), name, o.get("observed_on"), la[1], la[0], o.get("quality_grade"), o.get("uri")))
print("species:")
for s,n in sorted(spp.items(), key=lambda x:-x[1]):
    print(f"  {n:3d} {s}")
print("closest:")
for r in sorted(rows)[:20]:
    print(f"  {r[0]:5.2f}km {r[1]} {r[2]} {r[3]},{r[4]} {r[5]} {r[6]}")
'

